import "package:flutter_test/flutter_test.dart"; import "package:flutter/material.dart"; import "../lib/widgets/property_card.dart"; import "../lib/models/property.dart"; void main() { group("PropertyCard Widget Tests", () { testWidgets("should display property information", (WidgetTester tester) async { final property = Property(id: "123", title: "Test Property", description: "Test Description", type: "House", status: "For Sale", price: 500000, bedrooms: 3, bathrooms: 2, area: 2000, address: "123 Test St", city: "Test City", state: "TS", zipcode: "12345", images: [], amenities: [], createdAt: DateTime.now(), updatedAt: DateTime.now()); await tester.pumpWidget(MaterialApp(home: Scaffold(body: PropertyCard(property: property)))); expect(find.text("Test Property"), findsOneWidget); expect(find.text("\$500,000"), findsOneWidget); expect(find.text("3"), findsOneWidget); expect(find.text("2"), findsOneWidget); expect(find.text("2,000 sq ft"), findsOneWidget); }); testWidgets("should call onTap when tapped", (WidgetTester tester) async { bool tapped = false; final property = Property(id: "123", title: "Test Property", description: "Test Description", type: "House", status: "For Sale", price: 500000, bedrooms: 3, bathrooms: 2, area: 2000, address: "123 Test St", city: "Test City", state: "TS", zipcode: "12345", images: [], amenities: [], createdAt: DateTime.now(), updatedAt: DateTime.now()); await tester.pumpWidget(MaterialApp(home: Scaffold(body: PropertyCard(property: property, onTap: () { tapped = true; })))); await tester.tap(find.byType(InkWell)); expect(tapped, true); }); }); }
